package com.multiforge.protocol.messages.masterbound;

import com.multiforge.protocol.ExtendedByteBuf;

/**
 * Answer from the current chunk owner to a handover request.
 *
 * <p>The owner first stops producing updates for the chunk, writes its region,
 * entity and point-of-interest data through the master and only then answers
 * {@code ready = true}. A {@code false} answer (or no answer within the master's
 * timeout) leaves ownership with the current owner, so a server that still hosts
 * a real player in the chunk never gives it away.</p>
 *
 * <p>The {@code handoverId} is generated by the master and echoed by both sides;
 * a late answer for an already finished or timed-out handover is ignored.</p>
 *
 * @see RequestChunkHandoverMessage
 */
public class ChunkHandoverReadyMessage extends MasterBoundMessage {

    /** Logical world name. */
    public final String world;
    /** Chunk X coordinate. */
    public final int cx;
    /** Chunk Z coordinate. */
    public final int cz;
    /** Master-assigned handover id. */
    public final long handoverId;
    /** Whether the owner drained its data and is ready to lose ownership. */
    public final boolean ready;

    /**
     * @param world      logical world name
     * @param cx         chunk X
     * @param cz         chunk Z
     * @param handoverId master-assigned handover id
     * @param ready      {@code true} when the chunk was flushed and may move
     */
    public ChunkHandoverReadyMessage(String world, int cx, int cz, long handoverId, boolean ready) {
        this.world = world;
        this.cx = cx;
        this.cz = cz;
        this.handoverId = handoverId;
        this.ready = ready;
    }

    /**
     * @param byteBuf payload positioned after the message id
     */
    public ChunkHandoverReadyMessage(ExtendedByteBuf byteBuf) {
        world = byteBuf.readString();
        cx = byteBuf.readInt();
        cz = byteBuf.readInt();
        handoverId = byteBuf.readLong();
        ready = byteBuf.readBoolean();
    }

    @Override
    public void write(ExtendedByteBuf byteBuf) {
        byteBuf.writeString(world);
        byteBuf.writeInt(cx);
        byteBuf.writeInt(cz);
        byteBuf.writeLong(handoverId);
        byteBuf.writeBoolean(ready);
    }

    @Override
    public void handle(MasterBoundMessageHandler handler) {
        handler.handle(this);
    }
}
